/// A keyboard event as seen by the hold gesture.
public struct KeyStroke: Sendable, Equatable {
    /// The physical key that produces "v" together with ⌘ in the current layout.
    public var isPasteKey: Bool
    public var modifiers: KeyModifiers
    /// Key repeat generated by holding the key down.
    public var isRepeat: Bool
    /// Events CopyPal posted itself (synthesized ⌘V, replayed keys).
    public var isOwnSynthetic: Bool

    public init(isPasteKey: Bool, modifiers: KeyModifiers, isRepeat: Bool = false, isOwnSynthetic: Bool = false) {
        self.isPasteKey = isPasteKey
        self.modifiers = modifiers
        self.isRepeat = isRepeat
        self.isOwnSynthetic = isOwnSynthetic
    }

    /// ⌘V exactly (no ⇧/⌥/⌃): the only chord CopyPal intercepts.
    public var isPasteChord: Bool {
        isPasteKey && modifiers.isExactlyCommand
    }
}

public enum HoldGestureInput: Sendable, Equatable {
    case keyDown(KeyStroke)
    case keyUp(KeyStroke)
    case flagsChanged
    /// The hold timer started with `generation` fired.
    case thresholdElapsed(generation: Int)
    case popupClosed
    /// The event tap was disabled/re-enabled by the system; forget everything in flight.
    case tapReset
}

public enum HoldGestureDisposition: Sendable, Equatable {
    case pass
    case swallow
}

public enum HoldGestureEffect: Sendable, Equatable {
    case startTimer(generation: Int)
    case cancelTimer
    /// Post a synthesized ⌘V (the normal paste).
    case synthesizePaste
    /// Re-post the swallowed current event after the synthesized paste, keeping key order.
    case replayCurrentEvent
    case showPopup
}

public struct HoldGestureOutput: Sendable, Equatable {
    public var disposition: HoldGestureDisposition
    public var effects: [HoldGestureEffect]

    public init(_ disposition: HoldGestureDisposition, _ effects: [HoldGestureEffect] = []) {
        self.disposition = disposition
        self.effects = effects
    }

    public static let pass = HoldGestureOutput(.pass)
    public static let swallow = HoldGestureOutput(.swallow)
}

public enum HoldGestureState: Sendable, Equatable {
    case idle
    /// ⌘V is down, waiting for release (tap → paste) or the threshold (hold → popup).
    case waiting(generation: Int)
    /// The popup is open; the held V must not reach the target app.
    case holding
}

/// Decides for every keyboard event whether ⌘V is a short tap (normal paste) or a
/// hold (open the popup). Pure and synchronous: timers, posting events and UI are
/// effects carried out by the caller. See ROADMAP §1.7.
public struct HoldGestureStateMachine: Sendable {
    public private(set) var state: HoldGestureState = .idle
    /// When false (e.g. hold disabled for the frontmost app), ⌘V passes through untouched.
    public var isEnabled = true
    private var lastGeneration = 0

    public init() {}

    public mutating func handle(_ input: HoldGestureInput) -> HoldGestureOutput {
        switch input {
        case let .keyDown(stroke) where stroke.isOwnSynthetic,
             let .keyUp(stroke) where stroke.isOwnSynthetic:
            return .pass
        case .flagsChanged:
            return .pass
        case .tapReset:
            var effects: [HoldGestureEffect] = []
            if case .waiting = state {
                effects.append(.cancelTimer)
            }
            state = .idle
            return HoldGestureOutput(.pass, effects)
        default:
            break
        }

        switch state {
        case .idle:
            return handleIdle(input)
        case let .waiting(generation):
            return handleWaiting(input, generation: generation)
        case .holding:
            return handleHolding(input)
        }
    }

    private mutating func handleIdle(_ input: HoldGestureInput) -> HoldGestureOutput {
        guard case let .keyDown(stroke) = input, isEnabled, stroke.isPasteChord, !stroke.isRepeat else {
            return .pass
        }
        lastGeneration += 1
        state = .waiting(generation: lastGeneration)
        return HoldGestureOutput(.swallow, [.startTimer(generation: lastGeneration)])
    }

    private mutating func handleWaiting(_ input: HoldGestureInput, generation: Int) -> HoldGestureOutput {
        switch input {
        case let .keyDown(stroke) where stroke.isPasteKey:
            // Key repeat (or a lost key-up) of the held V.
            return .swallow
        case .keyDown:
            // Another key while ⌘V is down: it was a paste after all, then that key.
            state = .idle
            return HoldGestureOutput(.swallow, [.cancelTimer, .synthesizePaste, .replayCurrentEvent])
        case let .keyUp(stroke) where stroke.isPasteKey:
            state = .idle
            return HoldGestureOutput(.swallow, [.cancelTimer, .synthesizePaste])
        case let .thresholdElapsed(fired) where fired == generation:
            state = .holding
            return HoldGestureOutput(.pass, [.showPopup])
        default:
            return .pass
        }
    }

    private mutating func handleHolding(_ input: HoldGestureInput) -> HoldGestureOutput {
        switch input {
        case let .keyDown(stroke) where stroke.isPasteKey,
             let .keyUp(stroke) where stroke.isPasteKey:
            return .swallow
        case .popupClosed:
            state = .idle
            return .pass
        default:
            return .pass
        }
    }
}
